"""Comprehensive tests for synthstr.stringy module."""

from __future__ import annotations

import pytest

from synthstr.stringy import is_palindrome, reverse, truncate, word_count


# ── reverse ──────────────────────────────────────────────────────────────────


class TestReverse:
    @pytest.mark.parametrize(
        "input_str, expected",
        [
            ("hello", "olleh"),
            ("abcdef", "fedcba"),
            ("racecar", "racecar"),
            ("a", "a"),
            ("ab", "ba"),
        ],
        ids=["simple", "longer", "palindrome", "single-char", "two-chars"],
    )
    def test_reverse_typical(self, input_str: str, expected: str) -> None:
        assert reverse(input_str) == expected

    def test_reverse_empty(self) -> None:
        assert reverse("") == ""

    def test_reverse_unicode(self) -> None:
        assert reverse("café") == "éfac"

    def test_reverse_emoji(self) -> None:
        assert reverse("a😀b") == "b😀a"

    def test_reverse_whitespace_preserved(self) -> None:
        assert reverse("a b c") == "c b a"

    def test_reverse_is_involution(self) -> None:
        """Reversing twice yields the original string."""
        s = "double-flip"
        assert reverse(reverse(s)) == s


# ── is_palindrome ────────────────────────────────────────────────────────────


class TestIsPalindrome:
    @pytest.mark.parametrize(
        "text",
        [
            "racecar",
            "madam",
            "A man, a plan, a canal: Panama",
            "Was it a car or a cat I saw?",
            "No 'x' in Nixon",
        ],
        ids=["racecar", "madam", "panama", "car-cat", "nixon"],
    )
    def test_palindromes(self, text: str) -> None:
        assert is_palindrome(text) is True

    @pytest.mark.parametrize(
        "text",
        [
            "hello",
            "python",
            "almost racekar",
        ],
        ids=["hello", "python", "near-miss"],
    )
    def test_non_palindromes(self, text: str) -> None:
        assert is_palindrome(text) is False

    def test_empty_string(self) -> None:
        assert is_palindrome("") is True

    def test_single_character(self) -> None:
        assert is_palindrome("x") is True

    def test_ignores_case(self) -> None:
        assert is_palindrome("Aba") is True

    def test_ignores_non_alnum(self) -> None:
        assert is_palindrome("!@#a#@!") is True

    def test_only_non_alnum(self) -> None:
        """String with no alphanumeric chars is trivially a palindrome."""
        assert is_palindrome("!!!") is True

    def test_digits_palindrome(self) -> None:
        assert is_palindrome("12321") is True

    def test_digits_non_palindrome(self) -> None:
        assert is_palindrome("12345") is False

    def test_mixed_alnum_palindrome(self) -> None:
        assert is_palindrome("a1b1a") is True


# ── word_count ───────────────────────────────────────────────────────────────


class TestWordCount:
    @pytest.mark.parametrize(
        "text, expected",
        [
            ("hello world", 2),
            ("one", 1),
            ("the quick brown fox", 4),
            ("   leading and trailing   ", 3),
            ("multiple   spaces   between", 3),
        ],
        ids=["two-words", "single", "four-words", "leading-trailing", "multiple-spaces"],
    )
    def test_word_count_typical(self, text: str, expected: int) -> None:
        assert word_count(text) == expected

    def test_empty_string(self) -> None:
        assert word_count("") == 0

    def test_only_whitespace(self) -> None:
        assert word_count("   \t\n  ") == 0

    def test_tabs_and_newlines(self) -> None:
        assert word_count("a\tb\nc") == 3

    def test_single_character(self) -> None:
        assert word_count("x") == 1


# ── truncate ─────────────────────────────────────────────────────────────────


class TestTruncate:
    def test_no_truncation_when_within_limit(self) -> None:
        assert truncate("hello", 10) == "hello"

    def test_no_truncation_at_exact_limit(self) -> None:
        assert truncate("hello", 5) == "hello"

    def test_truncation_adds_ellipsis(self) -> None:
        result = truncate("hello world", 5)
        assert result == "hell\u2026"
        assert len(result) == 5

    def test_truncation_limit_1(self) -> None:
        result = truncate("hello", 1)
        assert result == "\u2026"

    def test_truncation_limit_0(self) -> None:
        assert truncate("hello", 0) == ""

    def test_empty_string_any_limit(self) -> None:
        assert truncate("", 0) == ""
        assert truncate("", 5) == ""

    def test_negative_limit_raises(self) -> None:
        with pytest.raises(ValueError, match="limit must be non-negative"):
            truncate("hello", -1)

    def test_negative_limit_large(self) -> None:
        with pytest.raises(ValueError):
            truncate("x", -100)

    @pytest.mark.parametrize(
        "limit",
        [2, 3, 6, 10],
        ids=["limit-2", "limit-3", "limit-6", "limit-10"],
    )
    def test_result_never_exceeds_limit(self, limit: int) -> None:
        s = "a long string that will be truncated"
        result = truncate(s, limit)
        assert len(result) <= limit

    def test_unicode_content_truncated(self) -> None:
        result = truncate("café latte", 5)
        assert result == "caf\u00e9\u2026"
        assert len(result) == 5

